    const milestoneRows=await env.DB.prepare("SELECT milestone_index,plan_json,assets_json FROM replay_session_milestones WHERE session_id=? ORDER BY milestone_index").bind(sessionId).all<Record<string,unknown>>();let milestones=milestoneRows.results.map((row)=>({index:Number(row.milestone_index),plan:parseJson<LiveReplayPlan>(row.plan_json,{} as LiveReplayPlan),assets:parseJson<LiveReplayAssets>(row.assets_json,{} as LiveReplayAssets)}));
