async function archiveFailedSession(request:Request,env:WorkerEnv,sessionId:string){
  const auth=await requireUser(request,env,"admin",{account:"principal"});if(auth.response||!auth.user)return auth.response!;
  const row=await env.DB.prepare("SELECT * FROM replay_sessions WHERE session_id=? AND owner_id=?").bind(sessionId,auth.user.userId).first<SessionRow>();
  if(!row)return Response.json({error:"replay_session_not_found"},{status:404});
  if(String(row.status)!=="failed")return Response.json({error:"only_failed_replay_sessions_can_be_archived"},{status:409});
  const removedArtifactCount=await deleteGeneratedImagesByGenerationPrefix(env.MEDIA,auth.user.userId,`replay-${sessionId}-`);
  const archived=await env.DB.prepare("UPDATE replay_sessions SET status='archived' WHERE session_id=? AND owner_id=? AND status='failed'").bind(sessionId,auth.user.userId).run();
  if(Number(archived.meta.changes??0)!==1)return Response.json({error:"replay_session_changed_before_archive"},{status:409});
  await appendAuditEvent(env,auth.user.streamId,"user","LiveReplaySessionArchived",{replay_session_id:sessionId,previous_status:"failed",removed_artifact_count:removedArtifactCount,error_message:row.error_message?String(row.error_message):null},sessionId);
  return Response.json({archived:true,sessionId,removedArtifactCount});
}

