async function grantApproval(request:Request,env:WorkerEnv){
  const auth=await requireUser(request,env,"admin",{account:"principal"});if(auth.response||!auth.user)return auth.response!;const consent=requireConsent(auth.user);if(consent)return consent;
  if(!enabled(env))return Response.json({error:"live_replay_disabled"},{status:403});if(!env.OPENAI_API_KEY)return Response.json({error:"provider_not_configured"},{status:503});
  if(automationDeclared(request))return Response.json({error:"direct_user_approval_required"},{status:403});
  const body=await request.json() as {phrase?:string;costAcknowledged?:boolean;directUserApproval?:boolean;confirmationVersion?:string;seed?:string;initiator?:string;approvedMaximumMicrousd?:number;allowUserBudgetOverride?:boolean;eventCount?:number;providerCoverage?:string;studyTypes?:string[];experienceProfile?:string};
  const seed=String(body.seed??"").trim().slice(0,1200);const profileRequest=replayProfileRequest(body.eventCount,body.providerCoverage,body.studyTypes,body.experienceProfile);const profile=replayGenerationProfile(profileRequest.eventCount,profileRequest.providerCoverage,profileRequest.studyTypes);
  if(body.phrase!==APPROVAL_PHRASE||!bool(body.costAcknowledged)||!bool(body.directUserApproval)||body.confirmationVersion!==CONFIRMATION_VERSION||body.initiator!=="direct-user")return Response.json({error:"explicit_live_replay_approval_required"},{status:428});
  const preflight=await costPreflight(env,auth.user.userId,seed,profileRequest);const approvedMaximum=Math.floor(Number(body.approvedMaximumMicrousd??0));
  if(!preflight.fitsReplayStructure)return Response.json({error:"replay_stream_too_short_for_milestones",cost:preflight},{status:409});
  if(approvedMaximum!==preflight.estimate.authorizationMicrousd)return Response.json({error:"cost_estimate_changed",cost:preflight},{status:409});
  if(!preflight.fitsWorkspace)return Response.json({error:"cost_budget_hard_cap_reached",scope:"workspace",cost:preflight},{status:429});
  if(!preflight.fitsUser&&!bool(body.allowUserBudgetOverride))return Response.json({error:"cost_budget_override_required",scope:"user",cost:preflight},{status:429});
  const structuralSampleSize=Math.min(profile.targetEventCount,Math.max(minimumLiveReplayEventCount(profile.milestoneCount),buildComprehensiveScenario().length*2));
  const structuralSample=buildComprehensiveScenario("theory:approval-structural-preflight",structuralSampleSize,{focusScenario:replayFocusScenarioForExperience(profileRequest.experienceProfile)});
  const structuralCoverage=evaluateReplayCoverage(structuralSample,SCENARIO_EVENT_TYPES);
  if(!structuralCoverage.passed)return Response.json({error:"replay_semantic_preflight_failed",failedChecks:structuralCoverage.checks.filter((check)=>!check.passed).map(({key,summary})=>({key,summary}))},{status:409});
  const approvalId=uuidV7();const requestedAt=new Date();const expiresAt=new Date(requestedAt.getTime()+5*60_000);
  const allowUserOverage=!preflight.fitsUser&&bool(body.allowUserBudgetOverride);
  await env.DB.batch([
    env.DB.prepare("INSERT INTO replay_approvals (approval_id,owner_id,confirmation_version,seed,requested_at,expires_at,consumed_at) VALUES (?,?,?,?,?,?,NULL)").bind(approvalId,auth.user.userId,CONFIRMATION_VERSION,seed,requestedAt.toISOString(),expiresAt.toISOString()),
    env.DB.prepare("INSERT INTO replay_cost_authorizations (approval_id,owner_id,pricing_version,estimated_microusd,reserved_microusd,maximum_microusd,allow_user_overage,created_at) VALUES (?,?,?,?,?,?,?,?)").bind(approvalId,auth.user.userId,preflight.estimate.pricingVersion,preflight.estimate.estimatedMicrousd,preflight.estimate.authorizationMicrousd,approvedMaximum,allowUserOverage?1:0,requestedAt.toISOString()),
    env.DB.prepare("INSERT INTO replay_approval_profiles (approval_id,event_count,provider_coverage,milestone_count,image_count,created_at) VALUES (?,?,?,?,?,?)").bind(approvalId,profile.targetEventCount,profile.requestedCoverage,profile.milestoneCount,profile.imageCount,requestedAt.toISOString()),
    env.DB.prepare("INSERT INTO replay_development_profiles (approval_id,study_types_json,created_at) VALUES (?,?,?)").bind(approvalId,JSON.stringify(profile.studyTypes),requestedAt.toISOString()),
    env.DB.prepare("INSERT INTO replay_experience_profiles (approval_id,experience_profile,created_at) VALUES (?,?,?)").bind(approvalId,profileRequest.experienceProfile,requestedAt.toISOString()),
  ]);
  await appendAuditEvent(env,auth.user.streamId,"user","LiveReplayApprovalGranted",{approval_id:approvalId,confirmation_version:CONFIRMATION_VERSION,expires_at:expiresAt.toISOString(),provider_operations:profile.operations,target_event_count:profile.targetEventCount,provider_coverage:profile.requestedCoverage,resolved_provider_coverage:profile.resolvedCoverage,provider_milestone_count:profile.milestoneCount,study_types:profile.studyTypes,experience_profile:profileRequest.experienceProfile,development_stages:profile.developmentStages.map((stage)=>stage.kind),composition_milestone_count:profile.compositionCount,image_count:profile.imageCount,reusable_session:true,coverage_contract_version:REPLAY_COVERAGE_CONTRACT_VERSION,pricing_version:preflight.estimate.pricingVersion,estimated_cost_microusd:preflight.estimate.estimatedMicrousd,authorized_cost_microusd:approvedMaximum,user_budget_override:allowUserOverage});
  return Response.json({approvalId,expiresAt:expiresAt.toISOString(),estimatedCostMicrousd:preflight.estimate.estimatedMicrousd,authorizedCostMicrousd:approvedMaximum,profile});
}

