export async function handleReplaySessions(request:Request,env:WorkerEnv,sessionPath=""){
  await ensureSchema(env);if(sessionPath){const parts=sessionPath.split("/").filter(Boolean);const sessionId=parts[0]??"";const action=parts[1]??"";if(action==="persona"&&request.method==="POST")return prepareReplayPersona(request,env,sessionId);if(action==="retry"&&request.method==="POST")return prepareReplayRetry(request,env,sessionId);if(action)return new Response("Not found",{status:404});if(request.method==="GET")return readSession(request,env,sessionId);if(request.method==="DELETE")return archiveFailedSession(request,env,sessionId);return new Response("Method not allowed",{status:405});}
  if(request.method==="GET")return listSessions(request,env);if(request.method==="POST")return createSession(request,env);return new Response("Method not allowed",{status:405});
}

export async function handleReplayApproval(request:Request,env:WorkerEnv){if(request.method!=="POST")return new Response("Method not allowed",{status:405});await ensureSchema(env);return grantApproval(request,env);}
